statement:
One table describes a company's reporting lines:

- `Employees(employee_id, employee_name, manager_id, salary, department)`: one row per employee; `employee_id` is unique. `manager_id` is the `employee_id` of the person they report to, and it is `null` only for the CEO. The reporting lines form a single tree under the CEO.

For **every** employee report:

- `employee_id` and `employee_name`;
- `level`: the CEO is level 1, their direct reports level 2, the people reporting to those level 3, and so on;
- `team_size`: how many employees are below them, directly or through any chain of managers (0 for someone with no reports);
- `budget`: their own salary plus the salaries of everyone counted in `team_size`.

Order the rows by `level` ascending, then `budget` descending, then `employee_name` ascending.

validator:
function validate(input) {
  const [{ Employees = [] }] = input;
  const boss = new Map(), names = new Set();
  let ceos = 0;
  for (const [id, name, manager, salary] of Employees) {
    if (id === null) return 'Every employee needs an employee_id.';
    if (boss.has(id)) return `employee_id ${id} appears twice.`;
    boss.set(id, manager);
    if (manager === null) ceos++;
    if (name === null || names.has(name.toLowerCase())) return 'employee_name values must be present and distinct.';
    names.add(name.toLowerCase());
    if (salary === null || salary < 0) return 'salary must be a non-negative number.';
  }
  if (Employees.length && ceos !== 1) return 'Exactly one employee must have a null manager_id.';
  const depth = new Map();
  for (const id of boss.keys()) {
    const path = [];
    let at = id;
    while (at !== null && !depth.has(at)) {
      if (!boss.has(at)) return `manager_id ${at} is not an employee.`;
      if (path.length > boss.size) return 'The reporting lines contain a cycle.';
      path.push(at);
      at = boss.get(at);
    }
    let d = at === null ? 0 : depth.get(at);
    for (let i = path.length - 1; i >= 0; i--) depth.set(path[i], ++d);
  }
  return null;
}

generator:
function generate(rand, size) {
  const pick = list => list[Math.floor(rand() * list.length)];
  const pool = ['Alice', 'Bob', 'Charlie', 'David', 'Eva', 'Frank', 'Grace', 'Hank', 'Ivy', 'Judy', 'Ken', 'Lena'];
  const n = size === 'small' ? Math.floor(rand() * 9) : 2000;
  // Distinct ids in a shuffled order, so the CEO is not always id 1 and managers may have larger ids.
  const ids = Array.from({ length: size === 'small' ? 15 : n }, (_, i) => i + 1);
  for (let i = ids.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [ids[i], ids[j]] = [ids[j], ids[i]]; }
  const names = size === 'small' ? [...pool] : null;
  if (names) for (let i = names.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [names[i], names[j]] = [names[j], names[i]]; }
  const salaries = size === 'small' ? [5000, 6000, 7000, 7500, 10000] : null;
  const rows = [];
  for (let i = 0; i < n; i++) {
    // Each employee reports to someone hired earlier; favouring recent hires makes deeper chains.
    const manager = i === 0 ? null : rows[rand() < 0.5 ? i - 1 - Math.floor(rand() * Math.min(i, 3)) : Math.floor(rand() * i)][0];
    const salary = salaries ? pick(salaries) : 3000 + 250 * Math.floor(rand() * 49);
    rows.push([ids[i], names ? names[i] : `Emp${String(ids[i]).padStart(4, '0')}`, manager, salary, pick(['Executive', 'Sales', 'Engineering'])]);
  }
  for (let i = rows.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [rows[i], rows[j]] = [rows[j], rows[i]]; }
  return [{ Employees: rows }];
}
